// Package gostarter shows how to plug strapgorm into a project generated by
// gostarter (github.com/faisalcayunda/gostarter), a zero-lock-in Go project
// generator that uses the port/adapter (hexagonal) repository pattern.
//
// # How this fits a gostarter project
//
// A gostarter domain package (for example internal/product) exposes a core
// Repository interface and a service constructed with NewService(repo). The
// concrete adapter that satisfies the interface lives next to it and owns the
// data-access technology. This file is exactly such an adapter: gormRepository
// implements Repository on top of *gorm.DB, and strapgorm turns the inbound
// Strapi query string into the SQL that backs Repository.List.
//
// # Driver compatibility (no conflict with gostarter's DB layer)
//
// gostarter opens its primary pool with the same underlying drivers GORM uses:
//
//   - Postgres: jackc/pgx/v5 + pgxpool. gorm.io/driver/postgres is pgx/v5-backed,
//     so a *gorm.DB opened over the same DATABASE_URL talks to the same server
//     through the same driver family.
//   - MySQL: database/sql + go-sql-driver/mysql. gorm.io/driver/mysql wraps
//     go-sql-driver/mysql, again the same driver gostarter uses.
//
// Because the drivers match, you can either open an independent *gorm.DB from
// the DATABASE_URL/DSN that gostarter already exposes (shown in OpenPostgres and
// OpenMySQL below) or, if you prefer a single pool, hand GORM an existing
// *sql.DB via the driver's Conn option. Either way there is no driver conflict.
package gostarter

import (
	"context"
	"fmt"

	"gorm.io/driver/mysql"
	"gorm.io/driver/postgres"
	"gorm.io/gorm"

	strapgorm "github.com/faisalcayunda/strapgorm"
	"github.com/faisalcayunda/strapgorm/paginate"
	"github.com/faisalcayunda/strapgorm/parser"
)

// Product is the domain model for this example. In a gostarter project it would
// live in internal/product/internal/core (the domain layer), free of any
// transport or persistence concern beyond its struct tags.
//
// The gorm tags describe the table mapping and the json tags name the fields as
// they appear in query strings and API responses. Implementing Searchable opts
// the model into strapgorm's free-text search over the listed fields.
type Product struct {
	ID          uint    `gorm:"primaryKey" json:"id"`
	Name        string  `gorm:"size:200;index" json:"name"`
	SKU         string  `gorm:"size:64;uniqueIndex" json:"sku"`
	Description string  `gorm:"type:text" json:"description"`
	Price       float64 `gorm:"not null" json:"price"`
	Stock       int     `gorm:"not null;default:0" json:"stock"`
	CategoryID  uint    `gorm:"index" json:"category_id"`
	Active      bool    `gorm:"not null;default:true" json:"active"`
}

// Searchable declares the JSON field names matched by the free-text "search"
// (or "_q") query parameter. strapgorm resolves each name against the schema
// whitelist and builds a case-insensitive OR predicate over the columns.
func (Product) Searchable() []string {
	return []string{"name", "sku", "description"}
}

// Repository is the core port a gostarter domain exposes for product retrieval.
// The service layer depends on this interface, not on GORM or strapgorm, so the
// persistence technology stays swappable.
type Repository interface {
	// List returns a page of products selected, filtered, sorted, and searched
	// according to the decoded Strapi query parameters, together with the
	// pagination metadata for the response envelope.
	List(ctx context.Context, qp parser.QueryParams) ([]Product, paginate.Meta, error)
}

// gormRepository is the GORM-backed adapter that satisfies Repository. It holds
// only the *gorm.DB handle; all query translation is delegated to strapgorm.
type gormRepository struct {
	db *gorm.DB
}

// NewGormRepository wires a Repository backed by db. In a gostarter project this
// is called from the composition root (for example the domain's wire/provider
// set), and the returned Repository is injected into NewService(repo).
func NewGormRepository(db *gorm.DB) Repository {
	return &gormRepository{db: db}
}

// List implements Repository by handing the decoded query parameters to
// strapgorm. FromParams applies the filter, sort, search, fields, and populate
// concerns; Paginate runs the page query (and the COUNT query when
// qp.Pagination.WithCount is set) and returns the rows with their metadata.
//
// Every field, relation, and operator in qp is validated against Product's
// schema whitelist inside strapgorm; an unknown token returns a wrapped error
// here and never reaches SQL. Operand values are always bound as parameters.
func (r *gormRepository) List(ctx context.Context, qp parser.QueryParams) ([]Product, paginate.Meta, error) {
	products, meta, err := strapgorm.New[Product](r.db).
		FromParams(qp).
		Paginate(ctx, qp.Pagination)
	if err != nil {
		return nil, paginate.Meta{}, fmt.Errorf("gostarter/product: list: %w", err)
	}
	return products, meta, nil
}

// OpenPostgres opens a *gorm.DB over the same DATABASE_URL a gostarter project
// exposes for its pgx/pgxpool pool. gorm.io/driver/postgres is pgx/v5-backed, so
// this reuses the same driver family and connects to the same database without
// conflicting with the application's primary pool.
//
//	db, err := gostarter.OpenPostgres(os.Getenv("DATABASE_URL"))
func OpenPostgres(databaseURL string) (*gorm.DB, error) {
	db, err := gorm.Open(postgres.Open(databaseURL), &gorm.Config{})
	if err != nil {
		return nil, fmt.Errorf("gostarter: open postgres for gorm: %w", err)
	}
	return db, nil
}

// OpenMySQL opens a *gorm.DB over the same DSN a gostarter project exposes for
// its database/sql + go-sql-driver/mysql pool. gorm.io/driver/mysql wraps
// go-sql-driver/mysql, so this reuses the same driver and database.
//
//	db, err := gostarter.OpenMySQL(os.Getenv("DATABASE_DSN"))
func OpenMySQL(dsn string) (*gorm.DB, error) {
	db, err := gorm.Open(mysql.Open(dsn), &gorm.Config{})
	if err != nil {
		return nil, fmt.Errorf("gostarter: open mysql for gorm: %w", err)
	}
	return db, nil
}
